  c.strokeStyle = 'rgba(40,20,30,.8)'; c.lineWidth = 1; c.beginPath(); c.moveTo(cx - bw / 2 + 6, y - 8); c.lineTo(cx - bw / 2 + 6, y); c.moveTo(cx + bw / 2 - 6, y - 8); c.lineTo(cx + bw / 2 - 6, y); c.stroke();
