  c.save(); c.strokeStyle = '#f2c94c'; c.lineWidth = 1.2; c.globalAlpha = 0.9; c.strokeRect(cx - bw / 2 + 2, y + 3, bw - 4, bh - 6);
  c.fillStyle = '#f2c94c';
