      var L = S.hh * 0.32, th = 0.35 * Math.cos(Math.sqrt(9.8 / (L / 40)) * S.t / 1000 + i), lx = x1 - 4 + Math.sin(th) * L, ly = top + S.hh * 0.25 + Math.cos(th) * L;
