    paper(c, rect(dx - S.hh * 0.42, sy - S.hh * 0.42, S.hh * 0.22, S.hh * 0.12), '#d9d0c0', 0.8);
    paper(c, rect(dx - S.hh * 0.62, sy - S.hh * 0.62 - hit * 3, S.hh * 0.28, 3), '#e8b84a', 0.6);
    /* guitar */
