      var nod = { lean: 0.08 + 0.05 * Math.sin(S.t / 1300 + i), seat: 0.24, legs: POSE.sit.legs, arms: (S.t / 2500 + i) % 7 < 0.6 ? [2.9, 0, 0.3, 0.6] : [0.7, 0.9, 0.6, 1] };
