    ground(c, S.x0, S.x1, S.deck, S.H, S.night ? '#2a1a14' : '#9a6a4a');
    var top = under(S, S.night ? '#3a2a5a' : '#6b5aa8'), sx0 = S.x0, sx1 = S.x1;
    var wx = S.x0 + S.span * 0.3, wy = S.deck - S.hh * 0.38;
