    function rad(f) { return r0 * (0.55 + 0.6 * Math.sin(Math.PI * Math.min(1, f * 1.05)) + 0.16 * Math.sin(k * Math.PI * f + phi)) + (f > 0.9 ? r0 * (f - 0.9) * 4 : 0); }
