    crew[0].dir = 1; crew[0].skirt = 0; person(c, wx - S.hh * 0.5, S.deck, S.hh * 0.95, { lean: 0.35, seat: 0.24, legs: POSE.sit.legs, arms: [1.3, 0.3, 1.2, 0.4] }, crew[0]);
