      c.strokeStyle = '#3b2a14'; c.lineWidth = 1.6; c.beginPath(); c.moveTo(me.hand[0][0], me.hand[0][1]); c.lineTo(me.hand[0][0] - S.hh * 0.1, me.hand[0][1] - 2); c.stroke();
