  c.fillStyle = 'rgba(232,200,150,.75)'; c.beginPath(); c.ellipse(low[0], low[1] + hh * 0.05, hh * 0.09 * Math.abs(Math.cos(a)) + 2, hh * 0.025, 0, 0, TAU); c.fill();
