  q.strokeStyle = 'rgba(255,255,255,.5)'; q.lineWidth = 1; for (var i = 1; i < 6; i++) { q.beginPath(); q.moveTo(x, y - r * 0.45); q.lineTo(x - r + i * r / 3, y); q.stroke(); }
