        if ((b * 3 + fi + f.seed) % 4 === 1) { fr(c, wx + ww + 3, wy + wh * 0.4, hh * 0.18, hh * 0.13, nt(S, '#e8e8e8')); c.strokeStyle = nt(S, '#9a9aa2'); c.beginPath(); c.arc(wx + ww + 3 + hh * 0.09, wy + wh * 0.4 + hh * 0.065, hh * 0.045, 0, TAU); c.stroke(); }
