  K.setting(S);
  if (o.neighbours) { if (L.fx0 - S.x0 > hh * 1.1) neighbour(c, S, S.x0 - 4, L.fx0 - hh * (o.gapL || 0.25), 1); if (S.x1 - L.fx1 > hh * 1.4) neighbour(c, S, L.fx1 + hh * (o.gapR || 0.25), S.x1 + 4, 2); }
