  c.fillStyle = '#2a1a12'; c.fillRect(x0 + w * 0.06, deck - hh * 0.1, w * 0.06, hh * 0.1); c.fillRect(x1 - w * 0.12, deck - hh * 0.1, w * 0.06, hh * 0.1);
