    for (k = 1; k < hats.length && k < shown; k++) { var a0 = G.at[hats[k - 1]], a1 = G.at[hats[k]], f = Math.min(1, shown - k); c.moveTo(a0[0], a0[1] - z * 0.5); c.lineTo(lerp(a0[0], a1[0], f), lerp(a0[1], a1[1], f) - z * 0.5); }
    c.stroke(); c.restore();
