  paper(c, poly([[x + 1 * u, y - u * 0.2], [x + flap * 1 * u, y - 1 * u * flap], [x - 1.5 * u + flap * 0.5 * u, y - 1.5 * u * flap], [x - 0.5 * u, y - u * 0.2]]), white, 1);
  
  // legs
  c.strokeStyle = leg; c.lineWidth = u * 0.16;
