  var wallCols = S.night ? ['#524636', '#4a3b3b', '#3a4a50', '#554433', '#403530', '#5a4a40', '#30404a'] : ['#a09070', '#b08a8a', '#809aa0', '#c09a70', '#a0857a', '#c0a080', '#7a9aa0'];
